<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {CalendarDays,UserRoundCog,History,Search,RefreshCw,Pencil,Phone,Users} from 'lucide-vue-next'
import CallAction from './CallAction.vue'
import IsolationProspectActivity from './IsolationProspectActivity.vue'
import IsolationVisits from './IsolationVisits.vue'
import SidePanel from './SidePanel.vue'
import IsolationBulkAssignment from './IsolationBulkAssignment.vue'
import IsolationDistribution from './IsolationDistribution.vue'
const adminTools=ref(false),callPending=ref(false),workflow=ref<'edit'|'call'>('edit')
const statuses=[['to_contact','À contacter'],['in_progress','En cours'],['callback','À rappeler'],['interested','Intéressé'],['not_interested','Non intéressé'],['unreachable','Non joint']]
type Column={key:string;label:string;rows:any[];count:number;page:number;next:boolean;busy:boolean;error:string}
const columns=ref<Column[]>([]),applied=ref({search:'',owner:'',due:false})
const visible=computed(()=>columns.value.filter(c=>(!commercialStatus.value||c.key===commercialStatus.value)&&(c.count>0||!!c.error)))
const total=computed(()=>visible.value.reduce((n,c)=>n+c.count,0))
let generation=0,disposed=false
const props=defineProps<{role:string;portal:(path:string,body?:any)=>Promise<any>;request:(path:string,body?:any,method?:string)=>Promise<any>}>()
const activityPanel=ref<any>(null),activityBusy=ref(false)
const visitsPanel=ref<any>(null),visitBusy=ref(false)
const visitsOpen=ref(false),visitProspect=ref<number|undefined>(undefined)
const activity=ref<any>(null),commercialStatus=ref(''),dueOnly=ref(false),callbacksDue=ref(0)
const rows=computed(()=>columns.value.flatMap(c=>c.rows)),search=ref(''),owner=ref(''),busy=ref(false),error=ref(''),selected=ref<any>(null),reason=ref('')
const people=ref<any[]>([]),peoplePage=ref(1),peopleCount=ref(0),peopleSearch=ref(''),target=ref(''),history=ref<any>(null),historyPage=ref(1),historyCount=ref(0),historyRows=ref<any[]>([])
async function run(action:()=>Promise<void>){busy.value=true;error.value='';try{await action()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function loadColumn(column:Column,version:number,append=false){
 if(append&&column.busy)return
 column.busy=true;column.error=''
 try{const q=new URLSearchParams({page:String(append?column.page+1:1),search:applied.value.search,owner:applied.value.owner,commercial_status:column.key,due:String(applied.value.due)})
  const data=await props.request(`work-queue/?${q}`);if(version!==generation||disposed)return
  column.rows=append?[...column.rows,...data.results]:data.results;column.count=data.count;column.next=!!data.next;column.page=append?column.page+1:1
 }catch(e:any){if(version===generation)column.error=e.message}finally{if(version===generation)column.busy=false}
}
async function load(){const version=++generation;busy.value=true;error.value='';applied.value={search:search.value.trim(),owner:owner.value,due:dueOnly.value}
 columns.value=statuses.map(([key,label])=>({key,label,rows:[],count:0,page:0,next:false,busy:true,error:''}))
 const queue=[...columns.value]
 await Promise.allSettled([props.request('workspace-dashboard/').then(data=>{if(version===generation)callbacksDue.value=data.callbacks_due}).catch(()=>{}),...Array.from({length:3},async()=>{while(queue.length&&!disposed&&version===generation)await loadColumn(queue.shift()!,version)})])
 if(version===generation)busy.value=false
}
async function openActivity(row:any,mode:'edit'|'call'='edit'){if(activity.value)return;await run(async()=>{workflow.value=mode;activity.value=await props.request(`work-queue/${row.id}/`)})}
function activityClosed(){if(callPending.value)return;activity.value=null;callPending.value=false;void load()}
async function directory(step=0){peoplePage.value=step?peoplePage.value+step:1;target.value='';const data=await props.portal(`isolation/setters/?page=${peoplePage.value}&search=${encodeURIComponent(peopleSearch.value)}`);people.value=data.results;peopleCount.value=data.count}
async function open(row:any){await run(async()=>{selected.value=await props.request(`work-queue/${row.id}/`);reason.value='';await directory()})}
async function assign(release=false){await run(async()=>{const row=selected.value;const body:any={revision:row.revision,reason:reason.value};if(!release)body.proof=(await props.portal('isolation/setters/',{prospect_id:row.id,setter_id:Number(target.value)})).proof;await props.request(`work-queue/${row.id}/${release?'unassign':'assign'}/`,body);selected.value=null;await load()})}
async function callIntent(row:any,id:string){
 const current=await props.request(`work-queue/${row.id}/`)
 if(activity.value?.id===current.id)activity.value=current
 return props.request(`work-queue/${row.id}/call-intent/`,{revision:current.revision,request_id:id})
}
async function loadHistory(){const data=await props.request(`work-queue/${history.value.id}/history/?page=${historyPage.value}`);historyRows.value=data.results;historyCount.value=data.count}
onMounted(async()=>{await load();if(props.role==='administrator')void run(()=>directory())})
onBeforeUnmount(()=>{disposed=true;generation++})
</script>
<template>
 <section class="prospects-board isolation-board">
  <header class="prospects-heading"><div><span>ESPACE ISOLATION · {{role==='administrator'?'ADMINISTRATION':'SETTER'}}</span><h1>Prospects</h1><p>Vos fiches, vos rappels et vos prochaines visites, au même endroit.</p></div><div class="board-actions"><button v-if="role==='administrator'" class="secondary" @click="adminTools=!adminTools"><Users :size="16"/>Répartir les prospects</button><button class="secondary" :disabled="busy" @click="load"><RefreshCw :size="16"/>Actualiser</button></div></header>
  <div class="prospects-toolbar"><label class="stage-filter"><select v-model="commercialStatus" aria-label="Filtrer les prospects par statut"><option value="">Tous les statuts</option><option v-for="[key,label] in statuses" :key="key" :value="key">{{label}}</option></select></label><span class="prospects-count" role="status">{{busy?'Chargement…':total+' prospect(s)'}}{{columns.some(c=>c.error)?' · résultat partiel':''}}</span><form @submit.prevent="load"><Search :size="17"/><input v-model="search" aria-label="Rechercher un prospect Isolation" placeholder="Nom, téléphone ou référence"><button :disabled="busy">Rechercher</button></form></div>
  <div class="isolation-filters"><label><input v-model="dueOnly" type="checkbox" @change="load">Rappels à traiter <span v-if="callbacksDue">({{callbacksDue}})</span></label><label v-if="role==='administrator'">Responsable<select v-model="owner" @change="load"><option value="">Tous les setters</option><option value="unassigned">Non affectés</option><option v-for="person in people" :key="person.id" :value="String(person.id)">{{person.name}}</option></select><input v-model="peopleSearch" aria-label="Rechercher un responsable" placeholder="Rechercher un setter" @change="run(()=>directory())"></label><button class="text-button" @click="visitProspect=undefined;visitsOpen=true"><CalendarDays :size="15"/>Consulter les visites</button></div>
  <p v-if="error" role="alert" class="error">{{error}}</p>
  <section v-if="adminTools&&role==='administrator'" class="admin-tools"><h2>Répartition et affectation</h2><p>Ces outils portent sur les {{rows.length}} fiches actuellement chargées. Filtrez ou chargez davantage de cartes pour préciser la sélection.</p><IsolationDistribution :rows="rows" :portal="portal" :request="request" @changed="load"/><IsolationBulkAssignment :rows="rows" :portal="portal" :request="request" @changed="load"/></section>
  <p v-if="!busy&&!visible.length" class="board-empty">Aucun prospect ne correspond à ces filtres.</p>
  <div class="prospects-columns" :class="{'single-status':visible.length===1}" role="region" tabindex="0" aria-label="Prospects Isolation par statut">
   <section v-for="column in visible" :key="column.key" class="prospect-column" :style="{'--stage-tone':['#f1ad54','#5b8def','#a18be2','#48b3be','#c990b8','#90a0b9'][columns.indexOf(column)%6]}">
    <header><span class="stage-dot"></span><h2>{{column.label}}</h2><span class="column-count">{{column.count}}</span></header><div class="prospect-stack">
     <p v-if="column.error" role="alert">{{column.error}}<button class="secondary" @click="loadColumn(column,generation,column.page>0)">Réessayer</button></p>
     <article v-for="row in column.rows" :key="row.id" class="prospect-card">
      <button class="prospect-title" @click="openActivity(row)">{{row.name||'Prospect sans nom'}}</button><small class="prospect-updated">{{row.campaign?.name||row.reference||'Isolation'}}</small>
      <div class="prospect-phone"><Phone :size="14"/><span>{{row.phone||row.raw_phone||'Non renseigné'}}</span><div class="number-actions"><button :aria-label="'Ouvrir la fiche de '+(row.name||'ce prospect')" title="Fiche et suivi" @click="openActivity(row)"><Pencil :size="15"/></button><button v-if="role==='setter'" class="phone-button" :disabled="!row.phone&&!row.raw_phone" :aria-label="'Préparer l’appel vers '+(row.phone||row.raw_phone)" title="Préparer l’appel" @click="openActivity(row,'call')"><Phone :size="15"/></button></div></div>
      <p class="prospect-email"><Users :size="14"/><span>{{row.assigned_setter?.name||'Non affecté'}}</span></p><p v-if="row.callback_at" class="prospect-reminder" :class="{'is-late':row.callback_due}">{{row.callback_due?'Rappel en retard':'Prochain rappel'}} · {{new Date(row.callback_at).toLocaleString('fr-FR')}}</p>
      <footer class="isolation-card-footer"><span class="prospect-stage">{{row.commercial_label||column.label}}</span><div><button title="Visites et formulaire C2" aria-label="Visites et formulaire C2" @click="visitProspect=row.id;visitsOpen=true"><CalendarDays :size="16"/></button><template v-if="role==='administrator'"><button title="Affecter ou réattribuer" aria-label="Affecter ou réattribuer" :disabled="busy" @click="open(row)"><UserRoundCog :size="16"/></button><button title="Historique d’affectation" aria-label="Historique d’affectation" @click="run(async()=>{history=row;historyPage=1;await loadHistory()})"><History :size="16"/></button></template></div></footer>
     </article>
     <button v-if="column.next" class="secondary more-prospects" :disabled="column.busy" @click="loadColumn(column,generation,true)">{{column.busy?'Chargement…':'Afficher plus'}} · {{column.rows.length}} / {{column.count}}</button>
    </div>
   </section>
  </div>
  <SidePanel :open="!!activity" :title="activity?.name||'Fiche et suivi'" eyebrow="ISOLATION" :close-disabled="activityBusy||callPending" @request-close="activityPanel?.close()"><CallAction v-if="activity&&role==='setter'" workspace="isolation" :resource-id="activity.id" :phone="activity.phone||activity.raw_phone" :auto-open="workflow==='call'" :before-open="async()=>{activity=await request(`work-queue/${activity.id}/`)}" :portal="portal" :prepare="(id:string)=>callIntent(activity,id)" :disabled="activityBusy" @busy="callPending=$event"/><IsolationProspectActivity v-if="activity" ref="activityPanel" :key="activity.id" :prospect-id="activity.id" :role="role" :portal="portal" :request="request" @busy="activityBusy=$event" @close="activityClosed" @saved="load" @book="visitProspect=activity.id;visitsOpen=true"/></SidePanel>
  <SidePanel :open="visitsOpen" title="Visites et formulaire C2" eyebrow="ISOLATION" :close-disabled="visitBusy" @request-close="visitsPanel?.close()"><IsolationVisits v-if="visitsOpen" ref="visitsPanel" :key="visitProspect||0" :prospect-id="visitProspect" :role="role" :portal="portal" :request="request" @busy="visitBusy=$event" @close="visitsOpen=false" @changed="load"/></SidePanel>
  <SidePanel :open="!!selected&&role==='administrator'" title="Affecter le prospect" eyebrow="ISOLATION · ADMINISTRATION" :close-disabled="busy" @request-close="selected=null"><section v-if="selected"><h4>Affectation : {{selected.name||selected.raw_phone}}</h4><form @submit.prevent="run(()=>directory())"><label>Rechercher un setter Isolation actif<input v-model="peopleSearch"></label><button class="secondary" :disabled="busy">Rechercher</button></form><form @submit.prevent="assign()"><label>Nouveau responsable<select v-model="target" required><option value="">Choisir un setter</option><option v-for="person in people" :key="person.id" :value="String(person.id)" :disabled="person.id===selected.assigned_setter?.id">{{person.name}}</option></select></label><p>{{peopleCount}} setter(s) · page {{peoplePage}}</p><button type="button" class="secondary" :disabled="busy||peoplePage===1" @click="run(()=>directory(-1))">Précédent</button><button type="button" class="secondary" :disabled="busy||peoplePage*25>=peopleCount" @click="run(()=>directory(1))">Suivant</button><label>Motif obligatoire<textarea v-model="reason" required maxlength="1000"></textarea></label><button class="primary" :disabled="busy||!target">Confirmer l’affectation</button><button type="button" class="secondary" :disabled="busy||!selected.assigned_setter||!reason.trim()" @click="assign(true)">Retirer l’affectation</button><button type="button" class="secondary" :disabled="busy" @click="selected=null">Fermer</button></form></section></SidePanel>
  <SidePanel :open="!!history" title="Historique d’affectation" eyebrow="ISOLATION · ADMINISTRATION" :close-disabled="busy" @request-close="history=null"><section v-if="history"><h4>Historique d’affectation</h4><article v-for="entry in historyRows" :key="entry.id"><small>{{new Date(entry.created_at).toLocaleString('fr-FR')}}</small><p>{{entry.metadata.before?.setter_name||'Non affecté'}} → {{entry.metadata.after?.setter_name||'Non affecté'}}</p><p v-if="entry.metadata.reason">{{entry.metadata.reason}}</p></article><button class="secondary" :disabled="busy||historyPage===1" @click="run(async()=>{historyPage--;await loadHistory()})">Précédent</button><button class="secondary" :disabled="busy||historyPage*25>=historyCount" @click="run(async()=>{historyPage++;await loadHistory()})">Suivant</button><button class="secondary" @click="history=null">Fermer l’historique</button></section></SidePanel>
 </section>
</template>
<style scoped>
.prospects-board{padding:28px;background:#f6f7fb;min-height:calc(100dvh - 78px);box-sizing:border-box;color:#26364d}.prospects-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}.prospects-heading span{font-size:10px;letter-spacing:1.3px;color:#8a97ad;font-weight:700}.prospects-heading h1{font-size:26px;letter-spacing:-.7px;margin:8px 0;color:#203249}.prospects-heading p{font-size:13px;color:#8693a5;margin:0;line-height:1.6}.prospects-toolbar{display:flex;align-items:center;gap:12px;margin-bottom:24px}.stage-filter{display:flex!important;align-items:center;background:white;border:1px solid #e1e6f0;border-radius:7px;padding-right:12px}.stage-filter select{appearance:none;background:none;border:0;padding:12px 30px 12px 13px;color:#6d7b90;min-width:170px;font-size:12px}.prospects-count{font-size:11px;color:#8794a7}.prospects-toolbar form{display:flex;align-items:center;gap:10px;background:white;border:1px solid #e1e6f0;border-radius:7px;padding:0 10px;margin-left:auto;color:#94a0b1}.prospects-toolbar input{border:0!important;background:none!important;padding:11px 0!important;font-size:12px;min-width:0}.prospects-toolbar form button{background:none;border:0;border-left:1px solid #edf0f5;padding:8px 0 8px 10px;font-size:11px;color:#527fe0;cursor:pointer}
.prospects-columns{display:flex;align-items:stretch;gap:16px;overflow-x:auto;height:calc(100dvh - 290px);min-height:360px;padding-bottom:12px;overscroll-behavior-x:contain}.prospect-column{flex:0 0 267px;min-width:0;display:flex;flex-direction:column;max-height:100%}.prospect-column>header{display:flex;align-items:center;gap:9px;background:white;padding:13px 12px;border-radius:7px;margin-bottom:12px;flex-shrink:0}.stage-dot{width:8px;height:8px;border-radius:50%;background:var(--stage-tone);flex-shrink:0}.prospect-column h2{font-size:12px!important;font-weight:600;margin:0;flex:1;color:#5f6c83}.prospect-column h2 small{display:block;color:#9aa4b3;font-size:10px;margin-top:3px}.column-count{font-size:10px;padding:4px 7px;background:#f0f4fa;border-radius:4px;color:#78869b}.prospect-stack{display:flex;flex-direction:column;gap:12px;overflow-y:auto;scrollbar-width:thin;padding-right:2px;min-height:0}.prospects-board .prospect-column .prospect-card{margin:0!important;border:1px solid #edf0f5!important;border-radius:8px!important;background:#fff;padding:17px!important;flex-shrink:0;box-shadow:0 2px 5px #34476c02}.prospect-title{display:block;font-size:13px;font-weight:600;color:#2d3b50;text-align:left;border:0;background:none;padding:0;cursor:pointer;width:100%;overflow-wrap:anywhere}.prospect-title:hover{color:#4378d8}.prospect-updated{display:block;color:#9aa3b2;font-size:10px!important;margin:7px 0 14px!important}.prospect-phone{border-top:1px solid #f0f2f6;padding-top:12px;display:flex;align-items:center;gap:7px;color:#8a95a7;font-size:11px}.prospect-phone>svg{flex-shrink:0}.prospect-phone>span{min-width:0;overflow-wrap:anywhere;flex:1}.number-actions{display:flex;gap:4px;flex-shrink:0}.number-actions button{display:grid;place-items:center;width:27px;height:27px;border:0;border-radius:6px;background:#f1f4fa;color:#8593ac;cursor:pointer}.number-actions button.phone-button{background:#eaf7f0;color:#4ca77e}.number-actions button:hover{box-shadow:0 0 0 2px #dce6f8}.prospect-email{display:flex;align-items:center;gap:7px;color:#8a95a7;font-size:11px;margin:9px 0 14px!important}.prospect-email svg{flex-shrink:0}.prospect-email span{overflow-wrap:anywhere;min-width:0}.prospect-stage{display:inline-block;border-radius:4px;background:color-mix(in srgb,var(--stage-tone) 14%,white);color:#68768d;padding:5px 8px;font-size:10px}.board-empty{font-size:12px;color:#a1aabc;text-align:center;padding:24px 10px}.more-prospects{width:100%;font-size:11px}.prospects-board button:disabled{opacity:.5;cursor:not-allowed}.prospect-dialog{width:min(1200px,95vw);max-width:95vw;max-height:92dvh;padding:0;border:0;border-radius:15px;box-shadow:0 22px 100px #15274244;color:#26364d;overflow:auto}.prospect-dialog::backdrop{background:#14243975;backdrop-filter:blur(3px)}.prospect-dialog:deep(.contact-editor){border:0;border-radius:0}.prospects-board button:focus-visible{outline:3px solid #b3cbf8;outline-offset:2px}
@media(max-width:720px){.prospects-board{padding:20px 14px}.prospects-toolbar{flex-wrap:wrap}.prospects-toolbar form{width:100%;margin:0}.prospects-toolbar input{flex:1}.prospects-heading h1{font-size:23px}.prospects-heading p{font-size:12px}.prospect-column{flex-basis:260px}.prospects-columns{height:65dvh}.prospect-dialog{width:96vw;max-width:96vw;max-height:95dvh}}
</style>
<style scoped>
